 {"id": "PEDS-C41-057", "sec": "Bacterial meningitis", "page": 189, "q": "After 2 years, and overall, the most common bacterial meningitis cause is —", "opts": ["Shigella dysenteriae", "Streptococcus pneumoniae", "E. coli", "H. influenzae"], "ans": 1, "exp": "Streptococcus pneumoniae. (Book p189)", "type": "mcq"},
 {"id": "PEDS-C41-058", "sec": "Bacterial meningitis", "page": 189, "q": "The commonest organism causing pyogenic meningitis in children overall is ___.", "opts": ["Streptococcus pneumoniae", "E. coli", "Haemophilus influenzae", "Group B Streptococcus"], "ans": 0, "exp": "Overall, Streptococcus pneumoniae is the leading organism; E. coli dominates 0–2 months and H. influenzae exceeds pneumococcus at 2–24 months. (Book p189)", "type": "fill"},
