 {"id": "PEDS-C41-060", "sec": "Bacterial meningitis", "page": 189, "q": "Raised ICP in an infant with meningitis presents with —", "opts": ["Bulging anterior fontanelle", "Frog-leg posture", "Sunken fontanelle", "Cortical thumb"], "ans": 0, "exp": "Bulging anterior fontanelle. (Book p189)", "type": "mcq"},
