 {"id": "PEDS-C41-063", "sec": "Bacterial meningitis", "page": 189, "q": "Signs of meningeal irritation are uncommon below age —", "opts": ["15 years", "10 years", "1 year", "4 years"], "ans": 3, "exp": "4 years. (Book p189)", "type": "mcq"},
 {"id": "PEDS-C41-064", "sec": "Bacterial meningitis", "page": 189, "q": "Nuchal rigidity refers to painful —", "opts": ["Neck flexion", "Knee flexion", "Hip extension", "Wrist flexion"], "ans": 0, "exp": "Neck flexion. (Book p189)", "type": "mcq"},
 {"id": "PEDS-C41-065", "sec": "Bacterial meningitis", "page": 189, "q": "In nuchal rigidity the child tends to keep the neck —", "opts": ["Rotated only", "Stiff", "Hyperextended only", "Floppy"], "ans": 1, "exp": "Stiff. (Book p189)", "type": "mcq"},
 {"id": "PEDS-C41-066", "sec": "Bacterial meningitis", "page": 189, "q": "Brudzinski sign is flexion of hips and knees in response to —", "opts": ["Ankle dorsiflexion", "Knee extension", "Neck flexion", "Hip extension"], "ans": 2, "exp": "Neck flexion. (Book p189)", "type": "mcq"},
 {"id": "PEDS-C41-067", "sec": "Bacterial meningitis", "page": 189, "q": "Kernig sign is resistance to knee extension while the —", "opts": ["Child is sitting", "Arm is raised", "Neck is flexed", "Hip is flexed"], "ans": 3, "exp": "Hip is flexed. (Book p189)", "type": "mcq"},
 {"id": "PEDS-C41-068", "sec": "Bacterial meningitis", "page": 189, "q": "Pain in Kernig sign is due to stretching of —", "opts": ["Inflamed meninges", "Renal capsule", "Calf muscle", "Hamstrings"], "ans": 0, "exp": "Inflamed meninges. (Book p189)", "type": "mcq"},
 {"id": "PEDS-C41-069", "sec": "Bacterial meningitis", "page": 189, "q": "The investigation of choice for meningitis is —", "opts": ["DMSA scan", "CSF analysis by lumbar puncture", "EEG", "USG KUB"], "ans": 1, "exp": "CSF analysis by lumbar puncture. (Book p189)", "type": "mcq"},
 {"id": "PEDS-C41-070", "sec": "Bacterial meningitis", "page": 189, "q": "Lumbar puncture is contraindicated with severe signs of —", "opts": ["Cough", "Low-grade fever", "Raised ICP", "Dysuria"], "ans": 2, "exp": "Raised ICP. (Book p189)", "type": "mcq"},
