 {"id": "PEDS-C41-075", "sec": "Bacterial meningitis", "page": 189, "q": "CSF sugar in bacterial meningitis is decreased, termed ___.", "opts": ["Pleocytosis", "Hyperproteinorrhachia", "Hyperglycorrhachia", "Hypoglycorrhachia"], "ans": 3, "exp": "Hypoglycorrhachia. (Book p189)", "type": "fill"},
