 {"id": "PEDS-C41-077", "sec": "Bacterial meningitis", "page": 189, "q": "The diagnosis is —", "opts": ["Neurocysticercosis", "Pyogenic meningitis", "TB meningitis", "Viral meningoencephalitis"], "ans": 1, "exp": "Turbid neutrophilic CSF with high protein and hypoglycorrhachia is bacterial/pyogenic meningitis. (Book p189)", "type": "case", "stem": "A 4-year-old has fever, irritability, neck stiffness, positive Kernig sign and turbid CSF with abundant neutrophils, increased protein and low sugar."},
 {"id": "PEDS-C41-078", "sec": "Bacterial meningitis", "page": 189, "q": "Odd one out (bacterial meningitis CSF profile):", "opts": ["High protein", "Turbid/cloudy CSF", "Lymphocyte predominance", "Abundant neutrophils"], "ans": 2, "exp": "Lymphocyte predominance suggests TB/viral patterns; bacterial CSF is turbid, neutrophilic and high protein with low sugar. (Book p189)", "type": "odd"},
 {"id": "PEDS-C41-079", "sec": "Meningitis treatment and TB pathogenesis", "page": 190, "q": "Pyogenic meningitis is initially treated with third-generation cephalosporin —", "opts": ["Isoniazid or rifampicin", "Acyclovir or ganciclovir", "Cephalexin or cefixime", "Ceftriaxone or cefotaxime"], "ans": 3, "exp": "Ceftriaxone or cefotaxime. (Book p190)", "type": "mcq"},
 {"id": "PEDS-C41-080", "sec": "Meningitis treatment and TB pathogenesis", "page": 190, "q": "If no response in 48 hours to initial cephalosporin, add —", "opts": ["Vancomycin", "Albendazole", "Dexamethasone alone", "ACTH"], "ans": 0, "exp": "Vancomycin. (Book p190)", "type": "mcq"},
 {"id": "PEDS-C41-081", "sec": "Meningitis treatment and TB pathogenesis", "page": 190, "q": "Antibiotics in bacterial meningitis can be changed after —", "opts": ["DMSA scan", "Culture and sensitivity results", "A single urine dipstick", "EEG results"], "ans": 1, "exp": "Culture and sensitivity results. (Book p190)", "type": "mcq"},
 {"id": "PEDS-C41-082", "sec": "Meningitis treatment and TB pathogenesis", "page": 190, "q": "The treatment duration of bacterial meningitis in a child is —", "opts": ["9–12 months", "2 days", "7–10 days", "3 weeks"], "ans": 2, "exp": "7–10 days. (Book p190)", "type": "mcq"},
