 {"id": "PEDS-C41-084", "sec": "Meningitis treatment and TB pathogenesis", "page": 190, "q": "Acute bacterial meningitis complications include seizures, brain abscess and —", "opts": ["Subdural effusion", "Cerebral palsy in all", "VP shunt obstruction only", "Cataracts"], "ans": 0, "exp": "Subdural effusion. (Book p190)", "type": "mcq"},
 {"id": "PEDS-C41-085", "sec": "Meningitis treatment and TB pathogenesis", "page": 190, "q": "The most common long-term meningitis complication is —", "opts": ["Anemia", "Sensorineural hearing loss", "Renal failure", "Muscle dystrophy"], "ans": 1, "exp": "Sensorineural hearing loss. (Book p190)", "type": "mcq"},
