 {"id": "PEDS-C41-088", "sec": "Meningitis treatment and TB pathogenesis", "page": 190, "q": "Steroids should be given with the ___ IV antibiotic dose in bacterial meningitis.", "opts": ["First", "Only after culture", "Last", "Only after 48 hours"], "ans": 0, "exp": "First. (Book p190)", "type": "mcq"},
